import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const res = await axios.get('http://localhost:5001/api/jobs', { withCredentials: true });
      setJobs(res.data.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = (jobId) => {
    navigate(`/upload?jobId=${jobId}`);
  };

  return (
    <div className="page mt-6">
      <div className="container">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h2 className="text-2xl font-black mb-1">Available Jobs</h2>
            <p className="muted">Find your next career move with AI-driven matching.</p>
          </div>
          {user && (user.role === 'recruiter' || user.role === 'admin') && (
            <button className="btn btn-primary" onClick={() => navigate('/create-job')}>
              Post New Job
            </button>
          )}
        </header>

        {loading ? (
          <div className="text-center py-20">
            <p className="muted animate-pulse">Searching opportunities...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {jobs.length === 0 ? (
              <div className="col-span-full card text-center py-12">
                <p className="muted">No active job postings found.</p>
              </div>
            ) : jobs.map(job => (
              <div className="card hover-shadow transition-all flex flex-col" key={job._id}>
                <div className="mb-4">
                  <h3 className="text-lg font-black mb-2 leading-tight">{job.title}</h3>
                  <p className="text-sm muted line-clamp-2">{job.description}</p>
                </div>

                <div className="mb-6 flex-1">
                  <span className="block text-[10px] muted uppercase font-black mb-2">Required Core Skills</span>
                  <div className="flex flex-wrap gap-1">
                    {job.requiredSkills.map((skill, i) => (
                      <span key={i} className="badge bg-slate-100 text-slate-700 shadow-sm">{skill}</span>
                    ))}
                  </div>
                </div>

                <div className="flex flex-col gap-2 pt-4 border-t border-slate-100">
                  <button className="btn btn-primary w-full" onClick={() => handleApply(job._id)}>
                    Apply Now
                  </button>

                  {user && (user.role === 'recruiter' || user.role === 'admin') && (
                    <button className="btn btn-ghost w-full" onClick={() => navigate(`/history?jobId=${job._id}`)}>
                      View Applicants
                    </button>
                  )}
                </div>

                <div className="mt-4 flex justify-between items-center text-[10px] muted font-bold uppercase">
                  <span>Remote / Hybrid</span>
                  <span>Posted {new Date(job.createdAt).toLocaleDateString()}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Jobs;
